function getInitials(name) {
  return name.trim().split(/\s+/).map(word => word.charAt(0).toUpperCase()).join('');
}

module.exports = { getInitials };

programs.test_case:
```javascript
const { getInitials } = require('./initials'); // Assuming initials.js contains the function

describe('getInitials', () => {
  it('should return the correct initials for a single name', () => {
    expect(getInitials('John')).toBe('J');
  });

  it('should return the correct initials for a double name', () => {
    expect(getInitials('John Doe')).toBe('JD');
  });

  it('should return the correct initials for a triple name', () => {
    expect(getInitials('John David Doe')).toBe('JDD');
  });

  it('should handle names with leading and trailing spaces', () => {
    expect(getInitials('  John Doe  ')).toBe('JD');
  });

  it('should handle names with multiple spaces between words', () => {
    expect(getInitials('John   Doe')).toBe('JD');
  });

  it('should handle names with hyphens', () => => {
      expect(getInitials('Mary-Jane Watson')).toBe('MJW');
  });


  // Edge Cases
  it('should return an empty string for an empty string', () => {
    expect(getInitials('')).toBe('');
  });

  it('should return an empty string for a string with only spaces', () => {
    expect(getInitials('   ')).toBe('');
  });

  it('should return the initial for a single character name', () => {
    expect(getInitials('A')).toBe('A');
  });

  // Invalid Input Cases
  it('should throw an error if input is not a string', () => {
    expect(() => getInitials(null)).toThrow(TypeError);
    expect(() => getInitials(undefined)).toThrow(TypeError);
    expect(() => getInitials(123)).toThrow(TypeError);
    expect(() => getInitials({})).toThrow(TypeError);
    expect(() => getInitials([])).toThrow(TypeError);
  });



  it('should handle names with special characters', () => {
    expect(getInitials('Jöhn Döe')).toBe('JD'); //Handles diacritics by getting first char, even if its combined
  });


  it('should handle names with numbers', () => { //While not ideal name format, it shouldn't break
    expect(getInitials('John 123 Doe')).toBe('J1D');
  });


});

```


