function isPositiveNumber(num) {
  return num > 0;
}

module.exports = { isPositiveNumber };

programs.test_case:
```javascript
const { isPositiveNumber } = require('./your-file-name'); // Replace 'your-file-name' with the actual file name

describe('isPositiveNumber', () => {
  it('should return true for positive numbers', () => {
    expect(isPositiveNumber(1)).toBe(true);
    expect(isPositiveNumber(10)).toBe(true);
    expect(isPositiveNumber(1000)).toBe(true);
    expect(isPositiveNumber(0.5)).toBe(true); // Test with decimal
    expect(isPositiveNumber(Number.MAX_VALUE)).toBe(true); // Test with largest positive number
  });

  it('should return false for zero', () => {
    expect(isPositiveNumber(0)).toBe(false); 
  });

  it('should return false for negative numbers', () => {
    expect(isPositiveNumber(-1)).toBe(false);
    expect(isPositiveNumber(-10)).toBe(false);
    expect(isPositiveNumber(-1000)).toBe(false);
    expect(isPositiveNumber(-0.5)).toBe(false); // Test with negative decimal
    expect(isPositiveNumber(Number.MIN_VALUE * -1)).toBe(false); // Large negative
  });



  it('should handle invalid input gracefully', () => {
    expect(isPositiveNumber(null)).toBe(false);
    expect(isPositiveNumber(undefined)).toBe(false);
    expect(isPositiveNumber(NaN)).toBe(false);
    expect(isPositiveNumber(Infinity)).toBe(true); // Infinity is considered positive
    expect(isPositiveNumber(-Infinity)).toBe(false);
    expect(isPositiveNumber('abc')).toBe(false); // Test with string input
    expect(isPositiveNumber({})).toBe(false);  // Test with object input
    expect(isPositiveNumber([])).toBe(false); // Test with array input

  });

});


```

