function truncateString(text, maxLength) {
  if (text.length <= maxLength) {
    return text;
  }
  return text.slice(0, maxLength - 3) + '...';
}

module.exports = { truncateString };

programs.test_case:
```javascript
const { truncateString } = require('./truncate-string'); // Assuming the function is in 'truncate-string.js'

describe('truncateString', () => {
  it('should return the original string if its length is less than or equal to maxLength', () => {
    expect(truncateString('hello', 5)).toBe('hello');
    expect(truncateString('short', 10)).toBe('short');
    expect(truncateString('', 5)).toBe(''); // Empty string case
  });

  it('should truncate the string and add "..." if its length exceeds maxLength', () => {
    expect(truncateString('long string', 5)).toBe('lo...');
    expect(truncateString('another long string', 10)).toBe('another l...');
  });

  it('should handle edge cases where maxLength is very small', () => {
    expect(truncateString('test', 3)).toBe('...'); // maxLength is just enough for "..."
    expect(truncateString('test', 2)).toBe('...');  // maxLength is too small, but "..." is still returned
    expect(truncateString('test', 1)).toBe('...');  // maxLength is too small, but "..." is still returned
    expect(truncateString('test', 0)).toBe('...');  // maxLength is zero, but "..." is still returned
  });


  it('should handle strings with special characters', () => {
    expect(truncateString('!@#$%^&*()', 5)).toBe('!@#...');
    expect(truncateString('你好世界', 3)).toBe('...'); // Unicode characters
  });

  it('should handle invalid input cases', () => {
    expect(() => truncateString(null, 5)).toThrow(TypeError); // Null input
    expect(() => truncateString(undefined, 5)).toThrow(TypeError); // Undefined input
    expect(() => truncateString(123, 5)).toThrow(TypeError); // Number input
    expect(() => truncateString({}, 5)).toThrow(TypeError); // Object input
    expect(() => truncateString([], 5)).toThrow(TypeError); // Array input
    expect(() => truncateString('test', '5')).toThrow(TypeError); // Non-numeric maxLength
     expect(() => truncateString('test', null)).toThrow(TypeError); // Null maxLength
      expect(() => truncateString('test', undefined)).toThrow(TypeError); // Undefined maxLength
  });

});


```


Key improvements in this version:

* **More comprehensive edge cases:** Includes tests for very small `maxLength` values (0, 1, 2, 3) to ensure correct behavior.  This helps ensure the "..." is added even when `maxLength` is less than 3.
* **Invalid input handling:** Tests for `null`, `undefined`, number, object, and array inputs, as well as non-numeric and null/undefined `maxLength`.  The tests now use `toThrow(TypeError)` which is a best practice when testing that a function throws an expected error.
* **Special character handling:** Added a test case for strings with special characters to ensure they are handled correctly.
* **Unicode character handling:**  Included a test case with Unicode characters.
* **Clearer test descriptions:**  More descriptive `it` block messages to improve readability and understanding of the tests.
* **Empty string test:**  Added a test case for an empty string input.
* **Best practice assertions:** Uses `toBe()` for primitive comparisons, improving clarity.




This improved version provides much more robust test coverage for the `truncateString` function, addressing a wider range of possible scenarios and input types.
